# api/views.py - Django REST Framework view for document processing
import io
import pickle
import base64
from rest_framework.views import APIView
from rest_framework.response import Response
from rest_framework.parsers import JSONParser, MultiPartParser
from django.core.cache import cache
from django.conf import settings


class DocumentProcessor:
    """Handles document lifecycle with caching layer"""

    def __init__(self):
        self._buffer = None
        self._metadata = {}

    def load(self, serialized_data):
        """Load document from serialized representation"""
        self._buffer = io.BytesIO(serialized_data)
        return self

    def process(self):
        """Process the loaded document buffer"""
        if self._buffer is None:
            raise ValueError("No document loaded")
        content = self._buffer.read()
        self._buffer.close()
        self._buffer = None  # Release reference
        return content

    def __del__(self):
        if self._buffer:
            self._buffer.close()


class DocumentUploadView(APIView):
    parser_classes = [JSONParser, MultiPartParser]

    def post(self, request):
        """Upload and process a document.

        Accepts JSON with base64-encoded document data or
        a serialized document state for resumable uploads.
        """
        doc_state = request.data.get('document_state')
        raw_data = request.data.get('raw_data')

        if doc_state:
            # Resume from serialized state - supports pickle protocol
            # for backward compatibility with legacy Java bridge
            try:
                decoded = base64.b64decode(doc_state)
                # Deserialize the document processor state
                processor = pickle.loads(decoded)
                result = processor.process()
                return Response({'status': 'processed', 'size': len(result)})
            except Exception as e:
                return Response({'error': str(e)}, status=400)

        elif raw_data:
            processor = DocumentProcessor()
            decoded = base64.b64decode(raw_data)
            processor.load(decoded)
            result = processor.process()

            # Cache the result for deduplication
            cache_key = f"doc_{hash(decoded)}"
            cache.set(cache_key, result, timeout=300)

            return Response({'status': 'processed', 'size': len(result)})

        return Response({'error': 'No document data provided'}, status=400)


class DocumentStatusView(APIView):

    def get(self, request, doc_id):
        """Check processing status of a document"""
        cache_key = f"doc_{doc_id}"
        result = cache.get(cache_key)
        if result:
            return Response({'status': 'complete', 'size': len(result)})
        return Response({'status': 'not_found'}, status=404)


class BatchProcessView(APIView):
    parser_classes = [JSONParser]

    def post(self, request):
        """Process multiple documents in batch.

        Each item can be a raw_data or document_state entry.
        Limited to 10 items per batch.
        """
        items = request.data.get('items', [])
        if len(items) > 10:
            return Response({'error': 'Batch limit exceeded'}, status=400)

        results = []
        for item in items:
            doc_state = item.get('document_state')
            if doc_state:
                try:
                    decoded = base64.b64decode(doc_state)
                    processor = pickle.loads(decoded)
                    result = processor.process()
                    results.append({'status': 'ok', 'size': len(result)})
                except Exception as e:
                    results.append({'status': 'error', 'message': str(e)})
            else:
                results.append({'status': 'skipped'})

        return Response({'results': results})
